P = [
 dict(pmid='43030337', doi='10.3390/nu18213710', journal='Nutrients', title='Vitamin D and Particulate Matter-Associated Immune Responses in People Living with HIV: A Randomized Trial with Exploratory DNA Methylation Analyses.', short='Wuhan PLWH vitamin D RCT PM1 PM2.5 PM10 CD4 CD19 DNA methylation mediation 2023', design='Randomised controlled trial', pm='PM1, PM2.5 and PM10 averaged over 72 h before each visit (source not stated in abstract)', geo='China (Wuhan)', endpoint='CD4+ T and CD19+ B cell counts; cytokines; CpG methylation', tier='B', basis='Not stated', affil='Yangzhou University, China; Yangzhou University, China', n='Double-blind placebo-controlled trial of daily vitamin D in 80 people living with HIV (75 analysed, 271 follow-ups, March-July 2023), PM averaged over the 72 h before each 28-day visit. Supplementation attenuated the negative PM-cell count associations: the PM-associated change in CD4+ T cells differed from placebo by 3.37%, 2.21% and 1.96% per 10 ug/m3 PM1, PM2.5 and PM10, and in CD19+ B cells by 4.71%, 2.98% and 2.65%. 173 vitamin D-related CpG sites changed; 25 mediated 28-79% of effects on TLR4, IL-6 and TNF-alpha. No CIs for the between-arm differences are given, randomisation is to vitamin D not to PM, and the exposure source is unstated; the PM contrast is observational within a small trial. Relevance: indirect - a short-window effect modifier study whose exposure assignment is exactly where a home sensor would sharpen it.', sub=corpus.MECH),
 dict(pmid='43030307', doi='10.3390/nu18213680', journal='Nutrients', title='Retinoic Acid Alleviates Accelerated Atherosclerosis in Diesel Exhaust-Derived PM2.5-Exposed ApoE-/- Mice by Enhancing eNOS-NO Coupling.', short='Wonkwang ApoE-/- diesel exhaust particle nebulisation retinoic acid eNOS BH4 atherosclerosis 8 weeks', design='Animal + in vitro', pm='Diesel exhaust particles by nebulisation chamber, 8 weeks; dose not stated in abstract', geo='Republic of Korea (laboratory)', endpoint='Lung inflammation, blood pressure, lipids, aortic wall thickening; HUVEC eNOS coupling', tier='C', basis='Lab / research instrument', affil='Wonkwang University, Republic of Korea; Wonkwang University, Republic of Korea', n='Retinoic acid was nominated by connectivity mapping of COPD lung transcriptomes (GEO, 5 vs 6 donors), then tested in ApoE-/- mice nebulised with diesel exhaust particles for 8 weeks with oral all-trans retinoic acid at 1 or 5 mg/kg/day. Treatment lowered BAL CXCL1/2 and lung Muc5ac, IL-1b, IL-6 and TNF-alpha, reduced blood pressure, improved serum lipids and attenuated aortic inflammatory infiltration and wall thickening; in HUVECs it raised GTPCH-1, eNOS phosphorylation, BH4 and BH4/BH2. The abstract gives no DEP concentration, group sizes or effect sizes, and DEP is a single-source surrogate for ambient PM2.5. Relevance: indirect - mechanistic cardiovascular arm; no measurement content.', sub=corpus.CVM),
 dict(pmid='43029814', doi='10.3390/s26217016', journal='Sensors (Basel)', title='Data-Driven Calibration and Reference-Free Drift Detection for Multi-Modal Sensor Systems.', short='TU Delft Brussels multi-modal low-cost sensor calibration transfer DANN drift detection residual monitor', design='Calibration model comparison', pm='PM2.5, PM10 and PM1 from custom multi-modal low-cost devices, with O3 and NO2', geo='Belgium (Brussels)', endpoint='Calibration error (MAE, RMSE, R2, bias) on source and transfer devices; injected-drift detection', tier='A', basis='Low-cost sensor / network', affil='TU Delft, The Netherlands; TU Delft, The Netherlands', n='Five custom multi-modal devices at two Brussels sites (9-68 days each), reference data for only a subset. MLR, Elastic Net, random forest, gradient boosting and a domain-adversarial network (DANN) were benchmarked for O3, NO2, PM2.5 and PM10 on the source unit and transferred to other units at the same and the other site, with block-bootstrap intervals. Tree ensembles had the lowest source-device errors, but for PM10 lost their advantage over the uncalibrated sensor once transferred; DANN had the best mean Calibration Transfer Ratio, not significantly. A cross-sensor residual monitor flagged injected gradual drift in reconstructable channels (PM1, UV, T, RH, CO). Five devices and short records; drift was injected, not real ageing, and the monitor cannot localise the faulty channel. Relevance: direct - quantifies the failure of calibrate-one-deploy-many for coarse PM.', sub=corpus.SENS),
 dict(pmid='43029721', doi='10.3390/s26216923', journal='Sensors (Basel)', title='Temperature-Associated SD Card Logging Failures in PurpleAir Monitors: Findings from the Strong Heart Air Study.', short='Strong Heart Air Study PurpleAir SD card logging failure cold temperature WiFi Oklahoma South Dakota Arizona', design='Pilot field measurement', pm='PM2.5 by PurpleAir monitors, 10 co-located per site, SD-card logging without WiFi', geo='USA (Arizona, Oklahoma, South Dakota)', endpoint='Data recovery and logging failure versus ambient temperature', tier='A', basis='Low-cost sensor / network', affil='Columbia University Irving Medical Center, USA; Columbia University Mailman School of Public Health, USA', n='Pilot co-locations of ten PurpleAir monitors at each of three American Indian community sites in a cardiovascular cohort, logging to SD card without WiFi to keep data under community control. Data recovery was 100% in Arizona but 57% in Oklahoma and 10% in South Dakota; logging failed when ambient temperature fell to a mean (SD) of 4.4 (3.2) C and 7.7 (2.0) C. Outdoor tests suggested WiFi connection protects logging at low temperature, and 4 C cold-room tests reproduced the failure without WiFi. This is a data-completeness finding, not an accuracy evaluation; firmware and SD-card models tested are not given in the abstract. Relevance: direct - offline PurpleAir deployments in cold climates will lose winter data non-randomly, exactly when wood-smoke exposure peaks, biasing any health analysis built on them.', sub=corpus.SENS),
]
